1	<?php
2	
3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Retail\CommissionPayout;
8	use App\Services\Stripe\CommissionVoidService;
9	use App\Services\Stripe\StripeConnectService;
10	use Illuminate\Http\JsonResponse;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\DB;
13	use Illuminate\Support\Facades\Log;
14	use Illuminate\Support\Str;
15	use Stripe\Exception\SignatureVerificationException;
16	use Stripe\Webhook;
17	
18	// V2: Core. Processes Stripe Connect events: account updates, checkout completions, transfer status, payment intents. Drives the commission payout lifecycle.
19	class StripeConnectWebhookController extends Controller
20	{
21	    public function __invoke(Request $request): JsonResponse
22	    {
23	        $payload = $request->getContent();
24	        $sigHeader = $request->header('Stripe-Signature');
25	
26	        if (! $sigHeader) {
27	            return response()->json(['error' => 'Missing signature'], 400);
28	        }
29	
30	        // Try both Connect and platform webhook secrets so one endpoint URL
31	        // can handle events from connected accounts and destination charges.
32	        $secrets = array_filter([
33	            config('services.stripe.connect_webhook_secret'),
34	            config('services.stripe.webhook_secret'),
35	        ]);
36	
37	        if ($secrets === []) {
38	            return response()->json(['error' => 'No webhook secret configured'], 400);
39	        }
40	
41	        $event = null;
42	        foreach ($secrets as $secret) {
43	            try {
44	                $event = Webhook::constructEvent($payload, $sigHeader, $secret);
45	                break;
46	            } catch (SignatureVerificationException) {
47	                continue;
48	            } catch (\Exception $e) {
49	                Log::warning('Stripe webhook parse error', ['error' => $e->getMessage()]);
50	
51	                return response()->json(['error' => 'Invalid payload'], 400);
52	            }
53	        }
54	
55	        if (! $event) {
56	            Log::warning('Stripe webhook signature verification failed for all configured secrets');
57	
58	            return response()->json(['error' => 'Invalid signature'], 400);
59	        }
60	
61	        // Idempotency: atomic insert-or-skip on the UNIQUE stripe_event_id.
62	        // Stripe event IDs are globally unique across platform + Connect events,
63	        // so billing.webhook_events covers both this controller and StripeWebhookController.
64	        // The insert is committed before the match() dispatch: if a handler throws a 500,
65	        // Stripe's retry will see the existing row and be short-circuited here rather than
66	        // re-triggering the crashing handler. Investigate via Nightwatch if that occurs.
67	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
68	            'id' => Str::uuid()->toString(),
69	            'stripe_event_id' => $event->id,
70	            'event_type' => $event->type,
71	            'payload' => json_encode(json_decode($payload, true)),
72	            'processed_at' => now(),
73	        ]);
74	
75	        if ($alreadyProcessed) {
76	            return response()->json(['received' => true]);
77	        }
78	
79	        return $this->handleParsedEvent($event);
80	    }
81	
82	    /**
83	     * Dispatch a verified, de-duplicated Stripe Event to the appropriate handler.
84	     * Extracted from __invoke() so it can be unit-tested without HMAC signing.
85	     *
86	     * Guards account-scoped event types by verifying the HMAC-signed top-level
87	     * `event->account` field matches `data.object->id`. A mismatch means the
88	     * payload was tampered with; we reject with 400 rather than mutating records.
89	     */
90	    public function handleParsedEvent(\Stripe\Event $event): JsonResponse
91	    {
92	        // For account-scoped events, event->account is the HMAC-signed source of truth.
93	        // If data.object.id differs, reject — payload could have been tampered with
94	        // to mutate a victim account using the attacker's valid HMAC.
95	        $accountScopedPrefixes = ['account.', 'capability.'];
96	        $isAccountScoped = collect($accountScopedPrefixes)
97	            ->contains(fn ($p) => str_starts_with($event->type, $p));
98	
99	        if ($isAccountScoped) {
100	            $topLevelAccount = $event->account ?? null;
101	            $objectId = $event->data->object->id ?? null;
102	
103	            if ($topLevelAccount === null || $topLevelAccount !== $objectId) {
104	                Log::warning('stripe.connect.account_mismatch', [
105	                    'event_id' => $event->id,
106	                    'event_account' => $topLevelAccount,
107	                    'object_id' => $objectId,
108	                ]);
109	
110	                return response()->json(['error' => 'account_mismatch'], 400);
111	            }
112	        }
113	
114	        match ($event->type) {
115	            'account.updated' => $this->handleAccountUpdated($event->data->object),
116	            'checkout.session.completed' => $this->handleCheckoutSessionCompleted($event->data->object, (string) ($event->account ?? '')),
117	            'transfer.created' => $this->handleTransferCreated($event->data->object),
118	            'transfer.failed' => $this->handleTransferFailed($event->data->object),
119	            'transfer.reversed' => $this->handleTransferFailed($event->data->object),
120	            'payment_intent.succeeded' => $this->handlePaymentIntentSucceeded($event->data->object, (string) ($event->account ?? '')),
121	            'payment_intent.payment_failed' => $this->handlePaymentIntentFailed($event->data->object),
122	            default => Log::debug('Unhandled Stripe Connect event', ['type' => $event->type]),
123	        };
124	
125	        return response()->json(['received' => true]);
126	    }
127	
128	    private function handleCheckoutSessionCompleted(object $checkoutSession, string $connectedAccountId): void
129	    {
130	        Log::debug('Stripe checkout session completed (no-op in V2)', [
131	            'checkout_session_id' => $checkoutSession->id ?? null,
132	            'connected_account_id' => $connectedAccountId,
133	        ]);
134	    }
135	
136	    private function handleAccountUpdated(object $account): void
137	    {
138	        $professional = Professional::where('stripe_connect_account_id', $account->id)->first();
139	
140	        if (! $professional) {
141	            Log::debug('Stripe account.updated for unknown account', ['account_id' => $account->id]);
142	
143	            return;
144	        }
145	
146	        // Respect local disconnect: if the professional has soft-disconnected
147	        // the account, ignore incoming Stripe events until they explicitly
148	        // reconnect via createOnboardingLink. Prevents a late account.updated
149	        // event from silently re-activating a disconnected account.
150	        if ($professional->stripe_connect_status === 'disconnected') {
151	            Log::debug('Stripe account.updated skipped — account locally disconnected', [
152	                'professional_id' => $professional->id,
153	                'account_id' => $account->id,
154	            ]);
155	
156	            return;
157	        }
158	
159	        $status = StripeConnectService::determineAccountStatus($account);
160	
161	        if ($professional->stripe_connect_status !== $status) {
162	            $oldStatus = $professional->stripe_connect_status;
163	            $professional->update(['stripe_connect_status' => $status]);
164	
165	            Log::info('Stripe Connect status updated', [
166	                'professional_id' => $professional->id,
167	                'old_status' => $oldStatus,
168	                'new_status' => $status,
169	            ]);
170	
171	            // When an affiliate transitions to 'active', flush any held commissions
172	            // so they enter the normal payout pipeline immediately.
173	            if ($status === 'active' && $oldStatus !== 'active') {
174	                try {
175	                    app(CommissionVoidService::class)->flushHeldCommissions($professional);
176	                } catch (\Throwable $e) {
177	                    Log::warning('Failed to flush held commissions on Stripe connect', [
178	                        'professional_id' => $professional->id,
179	                        'error' => $e->getMessage(),
180	                    ]);
181	                }
182	            }
183	        }
184	    }
185	
186	    private function handleTransferCreated(object $transfer): void
187	    {
188	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
189	
190	        if (! $payoutId) {
191	            return;
192	        }
193	
194	        Log::info('Stripe transfer created', [
195	            'transfer_id' => $transfer->id,
196	            'payout_id' => $payoutId,
197	        ]);
198	    }
199	
200	    private function handleTransferFailed(object $transfer): void
201	    {
202	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
203	
204	        if (! $payoutId) {
205	            return;
206	        }
207	
208	        $payout = CommissionPayout::find($payoutId);
209	        if ($payout && ! in_array($payout->status, ['failed', 'completed', 'cancelled'], true)) {
210	            $payout->update([
211	                'status' => 'failed',
212	                'failure_code' => 'transfer_failed_webhook',
213	                'failure_reason' => 'Transfer failed according to Stripe webhook',
214	            ]);
215	        }
216	
217	        Log::warning('Stripe transfer failed', [
218	            'transfer_id' => $transfer->id,
219	            'payout_id' => $payoutId,
220	        ]);
221	    }
222	
223	    private function handlePaymentIntentSucceeded(object $paymentIntent, string $connectedAccountId = ''): void
224	    {
225	        // Commission payout payment intent
226	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
227	        if (! $payoutId) {
228	            return;
229	        }
230	
231	        Log::info('Stripe payment intent succeeded for payout', [
232	            'payment_intent_id' => $paymentIntent->id,
233	            'payout_id' => $payoutId,
234	        ]);
235	    }
236	
237	    private function handlePaymentIntentFailed(object $paymentIntent): void
238	    {
239	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
240	
241	        if (! $payoutId) {
242	            return;
243	        }
244	
245	        $payout = CommissionPayout::find($payoutId);
246	        if ($payout && ! in_array($payout->status, ['failed', 'completed'])) {
247	            $payout->update([
248	                'status' => 'failed',
249	                'failure_code' => 'payment_failed_webhook',
250	                'failure_reason' => $paymentIntent->last_payment_error?->message ?? 'Payment failed',
251	            ]);
252	        }
253	
254	        Log::warning('Stripe payment intent failed for payout', [
255	            'payment_intent_id' => $paymentIntent->id,
256	            'payout_id' => $payoutId,
257	        ]);
258	    }
259	}
