3	namespace App\Services\Stripe;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Retail\CommissionLedgerEntry;
7	use App\Services\Notifications\NotificationPublisher;
8	use Illuminate\Support\Facades\DB;
9	use Illuminate\Support\Facades\Log;
10	
11	/**
12	 * Handles voiding commissions for affiliates who haven't connected Stripe.
13	 *
14	 * Two phases run on the daily cron:
15	 * 1. processVoidableCommissions() — void entries past their 30-day window
16	 * 2. sendGracePeriodWarnings() — nudge affiliates to connect Stripe
17	 *
18	 * Called from ProcessCommissionPayoutsJob after normal payout processing.
19	 */
20	class CommissionVoidService
21	{
22	    private int $voidWindowDays;
23	
24	    private int $gracePeriodDays;
25	
26	    public function __construct(private readonly NotificationPublisher $publisher)
27	    {
28	        $this->voidWindowDays = (int) config('sidest.store.commission_void_window_days', 30);
29	        $this->gracePeriodDays = (int) config('sidest.store.grace_period_days', 30);
30	    }
31	
32	    /**
33	     * Find and void all pending commissions past their void window
34	     * for affiliates without active Stripe accounts.
35	     *
36	     * @return array{voided_count: int, voided_cents: int}
37	     */
38	    public function processVoidableCommissions(): array
39	    {
40	        $cutoff = now()->utc()->subDays($this->voidWindowDays);
41	        $stats = ['voided_count' => 0, 'voided_cents' => 0];
42	
43	        // Chunk to avoid OOM on large result sets. Each entry is voided with
44	        // an optimistic lock so a concurrent flush won't be overwritten.
45	        CommissionLedgerEntry::query()
46	            ->whereNull('payout_id')
47	            ->where('entry_type', 'accrual')
48	            ->where('status', 'pending')
49	            ->where('occurred_at', '<=', $cutoff)
50	            ->whereHas('affiliateProfessional', function ($q) {
51	                $q->where('stripe_connect_status', '!=', 'active');
52	            })
53	            ->chunkById(500, function ($entries) use (&$stats) {
54	                foreach ($entries as $entry) {
55	                    try {
56	                        if ($this->voidEntry($entry, 'no_stripe_connected')) {
57	                            $stats['voided_count']++;
58	                            $stats['voided_cents'] += $entry->amount_cents;
59	                        }
60	                    } catch (\Throwable $e) {
61	                        Log::error('Failed to void commission entry', [
62	                            'entry_id' => $entry->id,
63	                            'error' => $e->getMessage(),
64	                        ]);
65	                    }
66	                }
67	            });
68	
69	        if ($stats['voided_count'] > 0) {
70	            Log::info('Commission void processing complete', $stats);
71	        }
72	
73	        return $stats;
74	    }
