240	    /**
241	     * Flush eligible held commissions when an affiliate connects Stripe.
242	     * Called from the webhook handler when status transitions to 'active'.
243	     *
244	     * Finds all pending commissions for this affiliate where the void window
245	     * hasn't expired, then marks them approved so the normal payout cron
246	     * picks them up.
247	     *
248	     * @return int Number of commissions flushed to approved
249	     */
250	    public function flushHeldCommissions(Professional $affiliate): int
251	    {
252	        $count = CommissionLedgerEntry::query()
253	            ->whereNull('payout_id')
254	            ->where('entry_type', 'accrual')
255	            ->where('status', 'pending')
256	            ->where('affiliate_professional_id', $affiliate->id)
257	            ->where('occurred_at', '>', now()->utc()->subDays($this->voidWindowDays))
258	            ->update(['status' => 'approved']);
259	
260	        if ($count > 0) {
261	            Log::info('Flushed held commissions on Stripe connect', [
262	                'affiliate_id' => $affiliate->id,
263	                'count' => $count,
264	            ]);
265	        }
266	
267	        return $count;
268	    }
269	
270	    /**
271	     * Check if an affiliate is within their grace period (Stripe not yet required).
272	     */
273	    public function isInGracePeriod(Professional $affiliate): bool
274	    {
275	        return $affiliate->stripe_grace_period_ends_at !== null
276	            && $affiliate->stripe_grace_period_ends_at->isFuture();
277	    }
278	
279	    /**
280	     * Batch-load pending commission totals for multiple affiliates in one query.
281	     *
282	     * @param  string[]  $affiliateIds
283	     * @return array<string, int> affiliate_id => total_pending_cents
284	     */
285	    /**
286	     * Voids up to $cap pending commission entries for a specific affiliate-brand pair.
287	     * Returns overflow: true (without voiding) when count exceeds cap — caller should
288	     * dispatch VoidPendingCommissionsForLinkJob instead.
289	     *
290	     * @return array{count: int, total_cents: int, overflow: bool}
291	     */
292	    public function voidPendingForAffiliateBrand(
293	        string $affiliateProfessionalId,
294	        string $brandProfessionalId,
295	        string $reason,
296	        int $cap = 200,
297	    ): array {
298	        $pendingCount = DB::table('commerce.commission_ledger_entries')
299	            ->where('affiliate_professional_id', $affiliateProfessionalId)
300	            ->where('brand_professional_id', $brandProfessionalId)
301	            ->where('status', 'pending')
302	            ->whereNull('payout_id')
303	            ->count();
304	
305	        if ($pendingCount > $cap) {
306	            return ['count' => 0, 'total_cents' => 0, 'overflow' => true];
307	        }
308	
309	        return $this->runVoidLoop($affiliateProfessionalId, $brandProfessionalId, $reason);
310	    }
311	
312	    /** Loops voidEntry() over every pending entry for the pair. */
313	    public function runVoidLoop(
314	        string $affiliateProfessionalId,
315	        string $brandProfessionalId,
316	        string $reason,
317	    ): array {
318	        $voidedCount = 0;
319	        $voidedCents = 0;
320	
321	        CommissionLedgerEntry::query()
322	            ->where('affiliate_professional_id', $affiliateProfessionalId)
323	            ->where('brand_professional_id', $brandProfessionalId)
324	            ->where('status', 'pending')
325	            ->whereNull('payout_id')
326	            ->orderBy('occurred_at')
327	            ->chunkById(50, function ($entries) use (&$voidedCount, &$voidedCents, $reason): void {
328	                foreach ($entries as $entry) {
329	                    if ($this->voidEntry($entry, $reason)) {
330	                        $voidedCount++;
331	                        $voidedCents += (int) $entry->amount_cents;
332	                    }
333	                }
334	            });
335	
336	        return ['count' => $voidedCount, 'total_cents' => $voidedCents, 'overflow' => false];
337	    }
338	
339	    /**
340	     * @return array{count: int, total_cents: int}
341	     */
342	    public function pendingSummaryForAffiliateBrand(
343	        string $affiliateProfessionalId,
344	        string $brandProfessionalId,
345	    ): array {
346	        $row = DB::table('commerce.commission_ledger_entries')
347	            ->where('affiliate_professional_id', $affiliateProfessionalId)
348	            ->where('brand_professional_id', $brandProfessionalId)
349	            ->where('status', 'pending')
350	            ->whereNull('payout_id')
351	            ->selectRaw('COUNT(*) AS c, COALESCE(SUM(amount_cents), 0) AS t')
352	            ->first();
353	
354	        return [
355	            'count' => (int) ($row->c ?? 0),
356	            'total_cents' => (int) ($row->t ?? 0),
357	        ];
358	    }
359	
360	    private function getPendingCommissionCentsBatch(array $affiliateIds): array
361	    {
362	        if ($affiliateIds === []) {
363	            return [];
364	        }
365	
366	        return CommissionLedgerEntry::query()
367	            ->whereNull('payout_id')
368	            ->where('entry_type', 'accrual')
369	            ->where('status', 'pending')
370	            ->whereIn('affiliate_professional_id', $affiliateIds)
371	            ->groupBy('affiliate_professional_id')
372	            ->pluck(\Illuminate\Support\Facades\DB::raw('SUM(amount_cents)'), 'affiliate_professional_id')
373	            ->map(fn ($v) => (int) $v)
374	            ->all();
375	    }
376	
377	    private function formatMoney(int $cents, string $currencyCode): string
378	    {
379	        $prefix = match (strtoupper($currencyCode)) {
380	            'USD' => '$',
381	            'GBP' => '£',
382	            'EUR' => '€',
383	            'AUD' => 'A$',
384	            default => strtoupper($currencyCode).' ',
385	        };
386	
387	        return $prefix.number_format($cents / 100, 2, '.', ',');
388	    }
389	}
