21	    /**
22	     * Create a Stripe Connect Express account for a professional/influencer/brand.
23	     *
24	     * Requires country_code to be set on the professional. Without it the
25	     * account would silently default to 'AU' and Stripe would later reject
26	     * the KYC form for non-AU users. Fail fast instead so the frontend can
27	     * prompt for country before onboarding.
28	     */
29	    public function createConnectAccount(Professional $professional): string
30	    {
31	        if (! is_string($professional->country_code) || trim($professional->country_code) === '') {
32	            abort(
33	                422,
34	                'Cannot create a Stripe Connect account without a country. Please set your country on your profile before connecting Stripe.'
35	            );
36	        }
37	
38	        $account = $this->stripe->accounts->create([
39	            'type' => 'express',
40	            'country' => $this->mapCountryCode($professional->country_code),
41	            'email' => $professional->primary_email,
42	            // Affiliates are individuals/sole traders — pre-selects the individual
43	            // KYC path so Stripe doesn't prompt with a business-type selector.
44	            'business_type' => 'individual',
45	            'metadata' => [
46	                'sidest_professional_id' => $professional->id,
47	                'professional_type' => $professional->professional_type,
48	            ],
49	            'capabilities' => [
50	                'transfers' => ['requested' => true],
51	                'card_payments' => ['requested' => true],
52	            ],
53	        ], ['idempotency_key' => "acct_{$professional->id}"]);
54	
55	        $professional->update([
56	            'stripe_connect_account_id' => $account->id,
57	            'stripe_connect_status' => 'onboarding',
58	            'stripe_grace_period_ends_at' => $professional->stripe_grace_period_ends_at
59	                ?? now()->addDays((int) config('sidest.store.grace_period_days', 30)),
60	        ]);
61	
62	        return $account->id;
63	    }
