65	    /**
66	     * Generate an onboarding link for a Connect Express account.
67	     *
68	     * If the professional previously soft-disconnected (status='disconnected'
69	     * but account_id preserved), reset their status to 'onboarding' so the
70	     * webhook handler stops skipping updates and the next account.updated
71	     * event flows through normally. Stripe KYC is preserved on the account,
72	     * so reconnecting is typically a one-click flow.
73	     */
74	    public function createOnboardingLink(Professional $professional, string $returnUrl, string $refreshUrl): string
75	    {
76	        $accountId = $professional->stripe_connect_account_id;
77	
78	        if (! $accountId) {
79	            $accountId = $this->createConnectAccount($professional);
80	        } else {
81	            if ($professional->stripe_connect_status === 'disconnected') {
82	                $professional->update(['stripe_connect_status' => 'onboarding']);
83	            }
84	
85	            // Patch business_type to 'individual' on any existing account that
86	            // hasn't finished onboarding yet. Stripe permits this update while
87	            // details_submitted is false — once submitted it's locked in.
88	            try {
89	                $existing = $this->stripe->accounts->retrieve($accountId);
90	                if (! $existing->details_submitted && $existing->business_type !== 'individual') {
91	                    $this->stripe->accounts->update($accountId, ['business_type' => 'individual']);
92	                }
93	            } catch (ApiErrorException) {
94	                // Non-fatal — continue with existing account as-is.
95	            }
96	        }
97	
98	        $link = $this->stripe->accountLinks->create([
99	            'account' => $accountId,
100	            'refresh_url' => $refreshUrl,
101	            'return_url' => $returnUrl,
102	            'type' => 'account_onboarding',
103	        ]);
104	
105	        return $link->url;
106	    }
