108	    /**
109	     * Check the status of a Connect account and sync it locally.
110	     *
111	     * If the professional is in the locally-disconnected state, we skip the
112	     * Stripe round-trip entirely — their account still exists at Stripe and
113	     * would return 'active', but the user has explicitly opted out. Let them
114	     * stay disconnected until they reconnect via createOnboardingLink.
115	     */
116	    public function syncAccountStatus(Professional $professional): array
117	    {
118	        $accountId = $professional->stripe_connect_account_id;
119	
120	        if (! $accountId) {
121	            return [
122	                'status' => 'not_connected',
123	                'charges_enabled' => false,
124	                'payouts_enabled' => false,
125	                'details_submitted' => false,
126	            ];
127	        }
128	
129	        if ($professional->stripe_connect_status === 'disconnected') {
130	            return [
131	                'status' => 'disconnected',
132	                'charges_enabled' => false,
133	                'payouts_enabled' => false,
134	                'details_submitted' => false,
135	            ];
136	        }
137	
138	        $account = $this->stripe->accounts->retrieve($accountId);
139	
140	        $status = self::determineAccountStatus($account);
141	
142	        if ($professional->stripe_connect_status !== $status) {
143	            $professional->update(['stripe_connect_status' => $status]);
144	        }
145	
146	        return [
147	            'status' => $status,
148	            'charges_enabled' => (bool) $account->charges_enabled,
149	            'payouts_enabled' => (bool) $account->payouts_enabled,
150	            'details_submitted' => (bool) $account->details_submitted,
151	            'requirements' => $account->requirements?->currently_due ?? [],
152	        ];
153	    }
