471	     * Idempotent by checkout session id.
472	     */
473	    public function confirmManualTopUpCheckoutSession(Professional $brand, string $sessionId): array
474	    {
475	        $existing = BrandCommissionTopup::query()
476	            ->where('stripe_checkout_session_id', $sessionId)
477	            ->first();
478	
479	        if ($existing) {
480	            $brand->refresh();
481	
482	            return [
483	                'status' => 'already_applied',
484	                'balance_cents' => (int) ($brand->stripe_manual_balance_cents ?? 0),
485	                'currency_code' => strtoupper((string) ($brand->stripe_manual_balance_currency ?: 'AUD')),
486	                'topup_id' => $existing->id,
487	            ];
488	        }
489	
490	        $session = $this->stripe->checkout->sessions->retrieve($sessionId);
491	
492	        if (($session->mode ?? null) !== 'payment') {
493	            throw new \RuntimeException('Checkout session is not a payment session.');
494	        }
495	
496	        if (($session->payment_status ?? null) !== 'paid') {
497	            throw new \RuntimeException('Top-up payment is not completed yet.');
498	        }
499	
500	        $metadataProId = $session->metadata?->sidest_professional_id ?? null;
501	        if ($metadataProId && $metadataProId !== $brand->id) {
502	            throw new \RuntimeException('Top-up session does not belong to this account.');
503	        }
504	
505	        $purpose = $session->metadata?->purpose ?? null;
506	        if ($purpose !== 'brand_commission_topup') {
507	            throw new \RuntimeException('Invalid top-up session purpose.');
508	        }
509	
510	        $amountCents = (int) ($session->amount_total ?? 0);
511	        if ($amountCents <= 0) {
512	            throw new \RuntimeException('Top-up amount is invalid.');
513	        }
514	
515	        $currency = strtoupper((string) ($session->currency ?: ($brand->stripe_manual_balance_currency ?: 'AUD')));
516	        $paymentIntentId = is_string($session->payment_intent)
517	            ? $session->payment_intent
518	            : ($session->payment_intent->id ?? null);
519	
520	        return DB::transaction(function () use ($brand, $sessionId, $paymentIntentId, $amountCents, $currency) {
521	            $lockedBrand = Professional::query()
522	                ->whereKey($brand->id)
523	                ->lockForUpdate()
524	                ->firstOrFail();
525	
526	            $existingTopup = BrandCommissionTopup::query()
527	                ->where('stripe_checkout_session_id', $sessionId)
528	                ->first();
529	
530	            if ($existingTopup) {
531	                return [
532	                    'status' => 'already_applied',
533	                    'balance_cents' => (int) ($lockedBrand->stripe_manual_balance_cents ?? 0),
534	                    'currency_code' => strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: 'AUD')),
535	                    'topup_id' => $existingTopup->id,
536	                ];
537	            }
538	
539	            $currentBalance = (int) ($lockedBrand->stripe_manual_balance_cents ?? 0);
540	            $currentCurrency = strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: $currency));
541	
542	            if ($currentCurrency !== $currency && $currentBalance > 0) {
543	                throw new \RuntimeException(
544	                    sprintf(
545	                        'Top-up currency %s does not match existing wallet currency %s.',
546	                        $currency,
547	                        $currentCurrency,
548	                    )
549	                );
550	            }
551	
552	            if ($currentCurrency !== $currency) {
553	                $lockedBrand->stripe_manual_balance_currency = $currency;
554	            }
555	
556	            $lockedBrand->stripe_manual_balance_cents = $currentBalance + $amountCents;
557	            $lockedBrand->save();
558	
559	            $topup = BrandCommissionTopup::create([
560	                'brand_professional_id' => $lockedBrand->id,
561	                'stripe_checkout_session_id' => $sessionId,
562	                'stripe_payment_intent_id' => $paymentIntentId,
563	                'amount_cents' => $amountCents,
564	                'currency_code' => $currency,
565	                'status' => 'completed',
566	            ]);
567	
568	            return [
