570	                'balance_cents' => (int) $lockedBrand->stripe_manual_balance_cents,
571	                'currency_code' => strtoupper((string) $lockedBrand->stripe_manual_balance_currency),
572	                'topup_id' => $topup->id,
573	            ];
574	        });
